const headers = $json.headers ?? {};
const suppliedKey = headers['x-jarvis-key'] ?? headers['X-Jarvis-Key'];
if (!suppliedKey || suppliedKey !== $env.JARVIS_API_KEY) {
  return [{ json: { ok: false, status: 401, error: 'Unauthorized' } }];
}
const body = $json.body ?? {};
const action = String(body.action ?? '').trim().toLowerCase();
const routes = {
  send_email: { path: '/webhook/jarvis/send-email', confirmation: 'SEND EMAIL' },
  send_telegram: { path: '/webhook/jarvis/send-telegram', confirmation: 'SEND MESSAGE' },
  desktop_action: { path: '/webhook/jarvis/desktop-action', confirmation: 'CONTROL PC' },
  web_research: { path: '/webhook/jarvis/web-research', confirmation: 'BROWSE WEB' },
};
if (!routes[action]) {
  return [{ json: { ok: false, status: 400, error: 'Unsupported action', supportedActions: Object.keys(routes) } }];
}
return [{
  json: {
    ok: true,
    action,
    endpoint: routes[action].path,
    requiredConfirmation: routes[action].confirmation,
    message: 'Validate the user request, present a preview, then call this endpoint with approved:true and the required confirmation.',
    payload: body,
  },
}];
